// 1. Redis 手动锁：SET NX PX 加锁 + Lua 校验释放
public class RedisLock {
    private final StringRedisTemplate redis;
    private static final String LOCK_PREFIX = "lock:";

    public boolean tryLock(String key, String token, long expireMs) {
        Boolean result = redis.opsForValue()
            .setIfAbsent(LOCK_PREFIX + key, token, expireMs, TimeUnit.MILLISECONDS);
        return Boolean.TRUE.equals(result);
    }

    public boolean unlock(String key, String token) {
        String luaScript = "if redis.call('get', KEYS[1]) == ARGV[1] " +
            "then return redis.call('del', KEYS[1]) else return 0 end";
        Long deleted = redis.execute(
            new DefaultRedisScript<>(luaScript, Long.class),
            Collections.singletonList(LOCK_PREFIX + key), token);
        return Long.valueOf(1L).equals(deleted);
    }
}

// 2. Redisson RLock：watchdog 续期 + 临界区幂等保护
@Service
public class OrderService {
    @Autowired
    private RedissonClient redisson;

    public void createOrder(String userId) throws InterruptedException {
        RLock lock = redisson.getLock("lock:order:" + userId);
        boolean locked = false;
        try {
            locked = lock.tryLock(5, -1, TimeUnit.SECONDS);
            if (!locked) throw new BusyException("系统繁忙");
            doCreateOrderWithIdempotency(userId); // 临界区内仍走幂等
        } finally {
            if (locked && lock.isHeldByCurrentThread()) {
                lock.unlock();
            }
        }
    }
}

// 3. ZooKeeper Curator 锁：临时顺序节点 + 超时
public class ZookeeperLock {
    private final InterProcessMutex lock;

    public ZookeeperLock(CuratorFramework client, String path) {
        this.lock = new InterProcessMutex(client, path);
    }

    public void executeWithLock(Runnable task, long timeout, TimeUnit unit) {
        boolean acquired = false;
        try {
            acquired = lock.acquire(timeout, unit);
            if (!acquired) throw new TimeoutException("获取锁超时");
            task.run();
        } catch (Exception e) {
            throw new RuntimeException("分布式锁异常", e);
        } finally {
            if (acquired) {
                try { lock.release(); }
                catch (Exception e) { throw new RuntimeException("释放失败", e); }
            }
        }
    }
}

// 4. 资源侧条件更新兜底：即使锁失效也不允许扣成负数
public void deductStock(String skuId, int quantity) {
    ZookeeperLock lock = new ZookeeperLock(zkClient, "/locks/stock/" + skuId);
    lock.executeWithLock(() -> {
        int updated = inventoryRepo.deductIfEnough(skuId, quantity);
        if (updated != 1) throw new InsufficientStockException();
    }, 10, TimeUnit.SECONDS);
}
